package io.github.long0823.tclbondriver;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Public station metadata only: deliberately discards the native Token field. */
final class IptvCatalog {
 static final class Channel {String name="",number="";int onid,tsid,sid;String id(){return onid+"-"+tsid+"-"+sid;}}
 final LinkedHashMap<String,Channel> channels=new LinkedHashMap<>();
 static IptvCatalog parse(byte[] bytes)throws IOException{if(bytes.length>262144)throw new IOException("Catalog too large");IptvCatalog c=new IptvCatalog();Channel channel=null;for(String line:new String(bytes,StandardCharsets.UTF_8).split("\\r?\\n")){line=line.trim();if(line.startsWith("[")){if(channel!=null)c.add(channel);channel=line.matches("\\[Channel[0-9]+\\]")?new Channel():null;continue;}int equals=line.indexOf('=');if(equals<1||channel==null)continue;String k=line.substring(0,equals),v=line.substring(equals+1);try{switch(k){case "Name":channel.name=v;break;case "DisplayNumber":channel.number=v;break;case "ONID":channel.onid=Integer.parseInt(v);break;case "TSID":channel.tsid=Integer.parseInt(v);break;case "ServiceID":channel.sid=Integer.parseInt(v);break;}}catch(NumberFormatException e){throw new IOException("Invalid channel",e);}}if(channel!=null)c.add(channel);if(c.channels.isEmpty())throw new IOException("No TV channels");return c;}
 private void add(Channel c)throws IOException{if(c.onid<1||c.onid>65535||c.tsid<1||c.tsid>65535||c.sid<1||c.sid>65535||c.name.isEmpty()||c.name.length()>160)throw new IOException("Invalid channel");if(c.number.matches("[0-9]{1,2}"))c.number=String.format(java.util.Locale.ROOT,"%03d",Integer.parseInt(c.number));channels.put(c.id(),c);if(channels.size()>512)throw new IOException("Too many channels");}
 private static String clean(String value){return value.replaceAll("[\\r\\n\\x00-\\x1f]","").replace('"','\'');}
 /** accessCode is a new, revocable IPTV-only credential; never the native key. */
 String playlist(String baseUrl,String iptvAccessCode,int tuner){if(!iptvAccessCode.matches("[a-f0-9]{48}"))throw new IllegalArgumentException("IPTV-only access code required");String prefix=baseUrl+"/iptv/"+iptvAccessCode;StringBuilder out=new StringBuilder("#EXTM3U url-tvg=\"").append(prefix).append("/epg.xml\" x-tvg-url=\"").append(prefix).append("/epg.xml\"\n");for(Channel ch:channels.values())out.append("#EXTINF:-1 tvg-id=\"").append(ch.id()).append("\" tvg-chno=\"").append(clean(ch.number)).append("\" tvg-name=\"").append(clean(ch.name)).append("\" group-title=\"TCL TV チューナー").append(tuner+1).append("\",").append(clean(ch.number)).append(' ').append(clean(ch.name)).append('\n').append(prefix).append("/tuner/").append(tuner).append("/channel/").append(ch.id()).append(".ts\n");return out.toString();}
}